import sys, dis, json, importlib.util
from pathlib import Path

# load test module
mod_path = Path('/testbed/qa_instances_eval/pybamm_qa/battery_model_options_init_def_use_intersection_suite/files/tests/qa/battery_model_options_init_def_use_intersection_suite_test.py')
spec = importlib.util.spec_from_file_location('qa_test_mod', mod_path)
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)
TestCls = mod.TestBatteryModelOptionsInitDefUseIntersectionQA

import pybamm
func = pybamm.BatteryModelOptions.__init__
code = func.__code__

tracked = {
    'SEI_option','default_options','dimensionality_option','extra_options',
    'mechanics_option','msmr_check_list','name','opt','option','options',
    'phases_option','plating_option','sei_option','thermal_option','val',
    'value','value_list','working_electrode_option'
}

instr_by_offset = {i.offset: i for i in dis.get_instructions(func)}
param_defs = {name: code.co_firstlineno for name in code.co_varnames[:code.co_argcount] if name in tracked}

def run_case(method_name):
    current_def = dict(param_defs)
    pairs = set()

    def tracer(frame, event, arg):
        if event == 'call' and frame.f_code is code:
            frame.f_trace_opcodes = True
            return tracer
        if frame.f_code is code and event == 'opcode':
            inst = instr_by_offset.get(frame.f_lasti)
            if inst is None:
                return tracer
            op = inst.opname
            line = inst.starts_line if inst.starts_line is not None else frame.f_lineno
            var = inst.argval
            if var in tracked:
                if op in ('LOAD_FAST', 'LOAD_DEREF', 'LOAD_NAME'):
                    d = current_def.get(var)
                    if d is not None:
                        pairs.add((var, d, line))
                elif op in ('STORE_FAST', 'STORE_DEREF', 'STORE_NAME'):
                    current_def[var] = line
        return tracer

    t = TestCls()
    sys.settrace(tracer)
    try:
        getattr(t, method_name)()
    finally:
        sys.settrace(None)
    return pairs

order = [f'test_case_{i:02d}' for i in range(1, 11)]
per_test = {name: run_case(name) for name in order}
inter = set.intersection(*(per_test[n] for n in order))

# sort as requested
sorted_pairs = sorted(inter, key=lambda x: (x[0], x[1], x[2]))

out = {
    'observed_def_use_pairs': [
        {'def_line': d, 'use_line': u, 'variable': v}
        for (v, d, u) in sorted_pairs
    ]
}

print(json.dumps(out, indent=2))
